{
  "description": "The creature is shown in right-facing side profile standing on a small patch of dirt and gravel against a plain light background. It has the overall body shape, proportions and posture of a stocky horse, with a large barrel-shaped trunk supported by four sturdy legs. The head, neck, legs and tail are covered in shaggy brown hair and fur, while the central trunk from behind the shoulders to the hips is covered in smooth, bare-looking skin that is dark gray on the back fading to pale cream on the belly and is densely covered with small raised white dots. The head is horse-like with an elongated muzzle, the neck is thick and arched, the mane is short and bristly, and the tail is long and hairy. All four feet end in hooves.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a horse head with an elongated muzzle, dark eye, large nostril, and closed mouth with whiskers around the muzzle and lower jaw",
      "where": "at the far right end of the body on top of the neck, facing right"
    },
    {
      "part": "ears",
      "looks_like": "two upright, pointed, brown hairy ears with inner fur detail",
      "where": "on top of the head, one slightly behind the other"
    },
    {
      "part": "mane",
      "looks_like": "a short, thick, shaggy and bristly brown mane with individual hairs visible",
      "where": "along the top dorsal edge of the neck from behind the ears to the shoulders"
    },
    {
      "part": "legs",
      "looks_like": "four thick, sturdy, straight legs covered in shaggy brown hair with visible joints at knee and hock",
      "where": "two forelegs under the chest at the front right and two hind legs under the hips at the rear left, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four rounded, dark brown hooves with a hard outer wall and slight hair over the coronet",
      "where": "at the bottom tip of each leg resting on the ground"
    },
    {
      "part": "tail",
      "looks_like": "a long, thick, hairy brown tail with coarse hanging hair",
      "where": "at the extreme left rear of the body extending down from the rump"
    },
    {
      "part": "scales",
      "looks_like": "numerous small, rounded, raised white bump-like scales or tubercles densely scattered over the skin",
      "where": "covering the entire trunk from the shoulders to the hips on the back, sides and belly"
    },
    {
      "part": "markings",
      "looks_like": "a gradient color pattern dark slate-gray on the dorsal back fading to light tan and cream on the ventral belly, overlaid with dense white speckling",
      "where": "over the whole bare-skinned central body region between the hairy neck/shoulders and the hairy hips/thighs"
    }
  ],
  "attached_objects": [],
  "animals": [
    "horse"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
